- 1 ވަނަ މުޙައްރަމް ޙަރާމް މަސް؛ 9 ވަނަ (ތާސޫޢާ) އަދި 10 ވަނަ (ޢާޝޫރާ) ދުވަހު ރޯދަ ހިފުން ސުންނަތް 9:36
- 2 ވަނަ ޞަފަރު
- 3 ވަނަ ރަބީޢުލްއައްވަލް
- 4 ވަނަ ރަބީޢުލްއާޚިރު
- 5 ވަނަ ޖުމާދަލްއޫލާ
- 6 ވަނަ ޖުމާދަލްއާޚިރާ
- 7 ވަނަ ރަޖަބު ޙަރާމް މަސް
- 8 ވަނަ ޝަޢުބާން މަހުގެ ގިނަ ދުވަސްވަރު ރޯދަ ހިފުން (ސުންނަތް)
- 9 ވަނަ ރަމަޟާން ފަރުޟު ރޯދަ؛ ލައިލަތުލް ޤަދްރު 2:183-185, 187; 97:1-5
- 10 ވަނަ ޝައްވާލް ޢީދުލްފިތުރު (1 ވަނަ)؛ ހަ ދުވަހުގެ ސުންނަތް ރޯދަ
- 11 ވަނަ ޒުލްޤަޢްދާ ޙަރާމް މަސް
- 12 ވަނަ ޒުލްޙިއްޖާ އަހަރުގެ އެންމެ ރަނގަޅު ދިހަ ދުވަސް؛ ފުރަތަމަ 9 ދުވަހު ރޯދަ ހިފުން (ސުންނަތް)؛ ޢަރަފާތު ދުވަސް (9 ވަނަ)؛ ޢީދުލްއަޟްޙާ (10 ވަނަ) ރޯދަ ހިފުން މަނާ؛ އައްޔާމުއްތަޝްރީޤު (11 ވަނަ-13 ވަނަ) ރޯދަ ހިފުން މަނާ 2:196-203; 22:27-28
- ހޯމަވާރާއި ބުރާސްފަތި ދުވަސް ރޯދަ ހިފުން (ސުންނަތް)
