ދިމާވާ އާޔަތްތައް
- = އަލިފް، ލާމް، މީމް. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = އެމީހުންނަކީ އެމީހުންގެ ރަބްބުގެ ޙަޟްރަތުން ތެދު ހިދާޔަތެއްގައި ތިބި މީހުންނެވެ، އަދި އެމީހުންނަކީ ކާމިޔާބުވާ މީހުންނެވެ. 2:5; 31:5
- = އޭ ބަނީ އިސްރާއީލުންނޭވެ، އަހަރެން ތިޔަބައިމީހުންނަށް ދެއްވި އަހަރެންގެ ނިޢުމަތާއި، އަހަރެން ތިޔަބައިމީހުން ޢާލަމުންނަށް (ޤައުމުތަކަށް) ވުރެ މަތިވެރިކުރެއްވި ކަން ހަނދާންކުރައްވާށެވެ. 2:47; 2:122
- = އެއީ ފާއިތުވެދިޔަ އުންމަތެކެވެ. އެމީހުން ހޯދި އެއްޗެއްގެ ނަތީޖާ އެމީހުންނަށް ލިބޭނެއެވެ، އަދި ތިޔަބައިމީހުން ހޯދި އެއްޗެއް ތިޔަބައިމީހުންނަށް ލިބޭނެއެވެ. އަދި އެމީހުން ކުރަމުން ދިޔަ ކަމެއްގެ ސުވާލު ތިޔަބައިމީހުންނަށް ނުކުރެވޭނެއެވެ. 2:134; 2:141
- = އެތަނުގައި ދާއިމީގޮތުން ދެމިތިބޭނެއެވެ. އެމީހުންގެ ޢަޒާބު ލުއިނުކުރެވޭނެއެވެ، އަދި އެމީހުންނަށް ފުރުޞަތެއް ނުދެވޭނެއެވެ. 2:162; 3:88
- = އެކަމަކު އޭގެ ފަހުން ތައުބާވެ އަމިއްލަ ނަފްސު ރަނގަޅުކުރި މީހުން މެނުވީއެވެ. ފަހެ ﷲ ފުއްސަވާ ރަޙްމަތްތެރި ކަމަކަށް ވޮޑިގެންވެއެވެ. 3:89; 24:5
- = އެކަމަކު ކާފިރުވެ އަހަރެމެންގެ އާޔަތްތައް ދޮގުކުރި މީހުން، އެމީހުންނަކީ ނަރަކައިގެ ރައްޔިތުންނެވެ. 5:10; 5:86
- = އަދި އެމީހުންގެ ރަބްބުގެ އާޔަތްތަކުގެ ތެރެއިން އެއްވެސް އާޔަތެއް އެމީހުންގެ ގާތަށް އަންނަނީ، އެއިން އެމީހުން ދުރަށް އެނބުރި ދިއުމަށް ފަހުއެވެ. 6:4; 36:46
- = އަދި ކަލޭގެފާނުގެ ކުރިން ރަސޫލުންނަށް މަލާމާތްކުރެވިއްޖެއެވެ، ނަމަވެސް އެމީހުންނަށް މަލާމާތްކުރި މީހުން އެމީހުން މަލާމާތްކުރަމުން ދިޔަ ކަމުން ވަށާލެވުނެވެ. 6:10; 21:41
- = ބުނައްވާށެވެ: "ހަމަކަށަވަރުން އަހަރެންގެ ރަބްބަށް އަހަރެން ނުކިޔަމަންތެރިވެއްޖެނަމަ ބޮޑު ދުވަހުގެ ޢަޒާބަށް އަހަރެން ބިރުގަންނަމެވެ." 6:15; 39:13
- = ފަހެ ބިންހެލުން އެމީހުން ހިފައިފިއެވެ، އަދި އެމީހުންގެ ގޭގައި (މަރުވެ) ބޯއަޅާލައިގެން ވެއްޓިފައި ހުއްޓެވެ. 7:78; 7:91
- = ފަހެ އޭނާގެ ދަނޑި އެއްލާލިއެވެ، އެވަގުތު އެއީ ފާޅުވެގެންވާ ސޮރެކެވެ. 7:107; 26:32
- = އަދި އޭނާގެ އަތް ނަގައިފިއެވެ، ފަހެ އެއީ ބަލާ މީހުންނަށް (އަލިކަމާއެކު) ހުދުވެފައިވާ އެއްޗެކެވެ. 7:108; 26:33
- = އެމީހުން ބުނެފިއެވެ: "އަހަރެމެން ޢާލަމުންގެ ރަބްބަށް އީމާންވީމެވެ." 7:121; 26:47
- = މޫސާގެ އަދި ހާރޫނުގެ ރަބްބަށެވެ. 7:122; 26:48
- = އަދި އަހަރެން އެމީހުންނަށް މުއްދަތު ދޭނަމެވެ. ހަމަކަށަވަރުން އަހަރެންގެ ރޭވުން ވަރުގަދައެވެ. 7:183; 68:45
- = އެއީ އެކަލާނގެއެވެ، އެކަލާނގެ ރަސޫލާ ހިދާޔަތާއި ޙައްޤު ދީނާއެކު ފޮނުއްވީ، އެ ދީނު ހުރިހާ ދީނަކަށްވުރެ މަތިވެރިކުރުމަށެވެ، ޝަރީކުކުރާ މީހުންނަށް އެކަން ނުރުހިގެންދިޔަސް. 9:33; 61:9
- = އޭ ނަބިއްޔާއެވެ، ކާފިރުންނާއި މުނާފިޤުންނާ ހަނގުރާމަކުރައްވާށެވެ، އަދި އެމީހުންނަށް ގަދަކަމާ ކުރައްވާށެވެ. އަދި އެމީހުންގެ ތިބޭނެ ތަނަކީ ނަރަކައެވެ، އަދި އެއީ ނުބައި ގޮސްބައިވެނިވެއެވެ. 9:73; 66:9
- = އަދި އެމީހުން ބުނެއެވެ: "ތިޔަބައިމީހުން ތެދުވެރިންނަމަ މި ވަޢުދަކީ ކޮންއިރެއްތޯއެވެ؟" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = އަދި އަހަރެމެން މޫސާ ފޮނުއްވީމެވެ އަހަރެމެންގެ އާޔަތްތަކާއި ސާފު ބާރާއެކުގައެވެ. 11:96; 40:23
- = އަދި އަހަރެމެން މޫސާއަށް ފޮތް ދެއްވީމެވެ، ނަމަވެސް އެއާ ބެހޭގޮތުން ތަފާތުވެއްޖެއެވެ. އަދި ކަލޭގެފާނުގެ ރަބްބުގެ ޙަޟްރަތުން ކުރިން ބަސްފުޅު ފާއިތުވެފައި ނުވާނަމަ އެމީހުންގެ ދެމެދު ނިންމާލެވިދިއުނީހެވެ. އަދި ހަމަކަށަވަރުން އެމީހުން އެކަމާ ބެހޭގޮތުން އުނދަގުލުވެރި ޝައްކެއްގައެވެ. 11:110; 41:45
- = އެއީ ﷲ އަށް ދަތިކަމެއް ނޫނެވެ. 14:20; 35:17
- = އަދި އަހަރެން އޭނާ ފުރިހަމަކޮށް، އަހަރެންގެ (ހެއްދެވި) ރޫޙުން އޭނާގެ ތެރެއަށް ޕުމްފުޅާލެއްވުމުން، އޭނާއަށް ސުޖޫދުގައި ވެއްޓިގެން ދާށެވެ. 15:29; 38:72
- = ފަހެ މަލާއިކަތުން ހުރިހާ އެންމެން އެކުގައި ސުޖޫދުކުރިއެވެ. 15:30; 38:73
- = (ﷲ) ވިދާޅުވިއެވެ: "ފަހެ އެތަނުން ނިކުމެގެން ދާށެވެ، އެހެނީ ކަލެއަކީ ބޭރުކުރެވިފައިވާ މީހެކެވެ." 15:34; 38:77
- = އޭނާ ބުނިއެވެ: "އޭ އަހަރެންގެ ރަބްބެވެ، ފަހެ އެމީހުން ދިރުއްވޭ ދުވަހާ ހަމައަށް އަހަރެންނަށް މުއްދަތު ދެއްވާށެވެ." 15:36; 38:79
- = (ﷲ) ވިދާޅުވިއެވެ: "ފަހެ ކަލެއަކީ މުއްދަތު ދެވިފައިވާ މީހުންގެ ތެރެއިންނެވެ." 15:37; 38:80
- = މަޢުލޫމު ވަގުތުގެ ދުވަހާ ހަމައަށެވެ." 15:38; 38:81
- = އެމީހުންގެ ތެރެއިން ކަލޭގެފާނުގެ ޚާއްޞަ އަޅުން މެނުވީއެވެ. 15:40; 38:83
- = ހަމަކަށަވަރުން ތަޤްވާވެރިން ތިބޭނީ ބަގީޗާތަކާއި ފޮހިތަކުގެ ތެރޭގައެވެ. 15:45; 51:15
- = އޭނާ ވިދާޅުވިއެވެ: "ފަހެ އޭ ރަސޫލުންނޭވެ، ތިޔަބައިމީހުންގެ ކަންތައްކަމަކީ ކޮބައިތޯއެވެ؟" 15:57; 51:31
- = އެމީހުން ބުނެފިއެވެ: "ހަމަކަށަވަރުން އަހަރެމެން ފޮނުއްވިފައިވަނީ ކުށްވެރި ޤައުމަކަށެވެ." 15:58; 51:32
- = އީމާންވެ އެމީހުންގެ އީމާންކަން ޒުލުމާއެކު ގުޅައިނުލި މީހުން، އެމީހުންނަށް ރައްކާތެރިކަން ލިބޭނެއެވެ، އަދި އެމީހުންނަކީ ހިދާޔަތްލިބިފައިވާ މީހުންނެވެ. 16:42; 29:59
- = އަހަރެމެން އެމީހުންނަށް ދެއްވި އެއްޗެއް އެމީހުން ދޮގުކުރުމަށެވެ. ފަހެ ޖެހިގެން ތިބޭށެވެ، އެހެނީ ތިޔަބައިމީހުންނަށް އަވަހަށް އެނގޭނެއެވެ. 16:55; 30:34
- = ދެން އޭނާ މަގެއް ހިފިއެވެ. 18:89; 18:92
- = ފިރުޢައުނުގެ ގާތަށް ދާށެވެ. ހަމަކަށަވަރުން އޭނާ ހައްދު ފަހަނައެޅިއެވެ. 20:24; 79:17
- = އަދި އެމީހުންގެ ޢައުރަތްތައް ރައްކައުތެރިކުރާ މީހުންނެވެ. 23:5; 70:29
- = އެމީހުންގެ އަނބިންނާއި ނުވަތަ އެމީހުންގެ ކަނާތް އަތް ވެރިވެފައިވާ މީހުންނާ މެނުވީއެވެ، އެހެނީ އެމީހުންނަށް ފާޑުކިޔެވޭކަށް ނެތެވެ. 23:6; 70:30
- = އެކަމަކު އޭގެ ބޭރުން އެދޭ މީހުން، އެމީހުންނަކީ ހައްދު ފަހަނައަޅާ މީހުންނެވެ. 23:7; 70:31
- = އަދި އެމީހުންގެ އަމާނާތްތަކާއި ވަޢުދުތަކަށް ސަމާލުވާ މީހުންނެވެ. 23:8; 70:32
- = އޭނާ ބުންޏެވެ: "އޭ އަހަރެންގެ ރަބްބެވެ، އަހަރެންނަށް އެހީތެރިވެދެއްވާށެވެ، އެހެނީ އެމީހުން އަހަރެން ދޮގުކުރިއެވެ." 23:26; 23:39
- = ޠާ، ސީން، މީމް. 26:1; 28:1
- = މިއީ ސާފު ފޮތުގެ އާޔަތްތަކެވެ. 26:2; 28:2
- = ހަމަކަށަވަރުން އެކަމުގައި ނިޝާނެއް ވެއެވެ، އަދި އެމީހުންގެ ގިނަ މީހުން އީމާންވާ މީހުންނަށް ނުވެއެވެ. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = އަދި ހަމަކަށަވަރުން ކަލޭގެފާނުގެ ރަބްބު، އެކަލާނގެއަކީ ބާރުގަދަ، ރަޙްމަތްތެރި ފަރާތެވެ. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = އަދި އަހަރެމެން އެހެން މީހުން ފެނުގައި ފެންގަނޑުވެ ގެއްލުނީމެވެ. 26:66; 37:82
- = ހަމަކަށަވަރުން އަހަރެންނަކީ ތިޔަބައިމީހުންނަށް އަމާނާތްތެރި ރަސޫލެކެވެ. 26:107; 26:125; 26:143; 26:162; 26:178
- = ފަހެ ﷲ އަށް ބިރުގަނެ އަހަރެންނަށް ކިޔަމަންވާށެވެ. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = އަދި އަހަރެން އޭގެ ބަދަލުގައި ތިޔަބައިމީހުންނާ އެއްވެސް އުޖޫރައެއް ނުއެދެމެވެ. އަހަރެންގެ އުޖޫރަ ހަމައެކަނި ޢާލަމުންގެ ރަބްބުގެ ޙަޟްރަތުންނެވެ. 26:109; 26:127; 26:145; 26:164; 26:180
- = ބަގީޗާތަކާއި ފޮހިތަކުގައެވެ. 26:147; 44:52
- = އެމީހުން ބުނެފިއެވެ: "ކަލެއަކީ ޖާދޫ ލިބިފައިވާ މީހުންގެ ތެރެއިންނެވެ." 26:153; 26:185
- = އެކަމަކު އޭނާގެ އަނބިމީހާ މެނުވީއެވެ، އަހަރެމެން އެ އަންހެނާ ފަހަތުގައި ބާކީވާ މީހުންގެ ތެރެއިން ކަމަށް ކަނޑައެޅީމެވެ. 26:171; 37:135
- = ދެން އަހަރެމެން އެހެން މީހުން ނައްތާލީމެވެ. 26:172; 37:136
- = އަދި އަހަރެމެން އެމީހުންގެ މައްޗަށް ވެހުނު (ހިލަ) ވެހުމެއް ވެހެއްކެވީމެވެ، އަދި އިންޒާރުދެވުނު މީހުންގެ ވެހުމަކީ ނުބައި ވެހުމެކެވެ. 26:173; 27:58
- = ފަހެ އަހަރެމެންގެ ޢަޒާބު އަވަސްކުރުމަށް ހެއްޔެވެ؟ 26:204; 37:176
- = ނަމާދު ޤާއިމްކޮށް ޒަކާތް ދޭ މީހުންނެވެ، އަދި އެމީހުން އާޚިރަތާ ބެހޭގޮތުން ޔަޤީންކުރާ މީހުންނެވެ. 27:3; 31:4
- = އަދި (ހަނދާންކުރައްވާށެވެ، އޭ މުޙައްމަދުގެފާނެވެ) އެކަލާނގެ އެމީހުންނަށް ގޮވާލައްވައި ވިދާޅުވާނެ ދުވަހު: "ތިޔަބައިމީހުން ދަޢުވާކުރަމުން ދިޔަ އަހަރެންގެ 'ޝަރީކުން' ކޮބައިތޯއެވެ؟" 28:62; 28:74
- = އަދި އަހަރެމެންގެ ކާބަފައިންނަށްވެސް؟ 37:17; 56:48
- = އަދި އެމީހުން އެކަކު އަނެކަކާ ކުރިމަތިލައި ސުވާލުކުރާނެއެވެ. 37:27; 52:25
- = އެކަމަކު ﷲ ގެ ޚާއްޞަ އަޅުންނެވެ. 37:40; 37:74; 37:128; 37:160
- = ނިޢުމަތުގެ ބަގީޗާތަކުގައެވެ. 37:43; 56:12
- = އަދި އަހަރެމެން އޭނާއަށްޓަކައި ފަހުގެ ޖީލުތަކުގައި (ރަނގަޅު ބަސްފުޅު) ދޫކޮށްލީމެވެ: 37:78; 37:108; 37:129
- = ހަމަކަށަވަރުން އަހަރެމެން ހެޔޮކުރާ މީހުންނަށް އެގޮތަށް ބަދަލުދެމެވެ. 37:80; 37:121; 37:131; 77:44
- = ހަމަކަށަވަރުން އޭނާއަކީ އަހަރެމެންގެ އީމާންވެރި އަޅުންގެ ތެރެއިންނެވެ. 37:81; 37:111; 37:132
- = ތިޔަބައިމީހުންނަށް ކޮބައިތޯއެވެ؟ ތިޔަބައިމީހުން ޙުކުމްކުރަނީ ކިހިނެއްތޯއެވެ؟ 37:154; 68:36
- = އެއީ ޢާލަމުންނަށް ހަނދާންކޮށްދިނުމެއް ފިޔަވައި އެހެން އެއްޗެއް ނޫނެވެ. 38:87; 81:27
- = ފޮތުގެ ބާވައިލެވުމަކީ ބާރުގަދަ، ޙިކުމަތްތެރި ﷲ ގެ ޙަޟްރަތުންނެވެ. 39:1; 45:2; 46:2
- = ޙާ، މީމް. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = ސާފު ފޮތުގެ ޤަސަމްފުޅެވެ. 43:2; 44:2
- = ފަހެ އެމީހުންނަށް ވަޢުދުވެފައިވާ އެމީހުންގެ ދުވަހު ބައްދަލުވަންދެން، އެމީހުން ބޭކާރު ވާހަކަދައްކައި ކުޅެލަން ދޫކޮށްލައްވާށެވެ. 43:83; 70:42
- = (އެމީހުންނަށް ބުނެވޭނެއެވެ): "ތިޔަބައިމީހުން ކުރަމުން ދިޔަ ކަމުގެ ބަދަލުގައި ހިތްހަމަޖެހިގެން ކައިބުއިބަލާށެވެ." 52:19; 77:43
- = ނުވަތަ ކަލޭގެފާނު އެމީހުންގެ ކިބައިން އުޖޫރައެއް އެދެނީތޯއެވެ، ފަހެ އެމީހުން ދަރަނީގެ ބުރައިން ބުރަވެފައިތޯއެވެ؟ 52:40; 68:46
- = ނުވަތަ އެމީހުންގެ އަތުގައި ނުފެންނަ ކަންތައްތަކުގެ ޢިލްމުވޭތޯއެވެ، ފަހެ އެމީހުން (އެކަން) ލިޔަނީތޯއެވެ؟ 52:41; 68:47
- = އަދި އަހަރެންގެ ޢަޒާބާއި އިންޒާރު ކިހާ (ގަދަ) ވެގެންވީ ހެއްޔެވެ. 54:16; 54:21; 54:30
- = އަދި ހަމަކަށަވަރުން އަހަރެމެން ޤުރުއާނު ހަނދާންކުރުމަށް ފަސޭހަކުރެއްވީމެވެ. ފަހެ ހަނދާންކުރާ މީހަކު ހުރިހެއްޔެވެ؟ 54:17; 54:22; 54:32; 54:40
- = ފަހެ ތިޔަބައިމީހުންގެ ރަބްބުގެ ނިޢުމަތްތަކުގެ ތެރެއިން ކޮން ނިޢުމަތެއް ތިޔަބައިމީހުން ދޮގުކުރާނީ ހެއްޔެވެ؟ 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = ކުރީގެ މީހުންގެ ތެރެއިން (ބޮޑު) ޖަމާޢަތެއް. 56:13; 56:39
- = އަދި އަހަރެމެން (އެހެންވީމާ) ޙަރަމްކުރެވިފައިވާ މީހުންނެއްތޯއެވެ؟ 56:67; 68:27
- = ފަހެ ކަލޭގެފާނުގެ ރަބްބުގެ ނަން، އެންމެ ބޮޑު ރަބްބުގެ ނަން ތަސްބީޙަކުރައްވާށެވެ. 56:74; 56:96; 69:52
- = [އެއީ] ޢާލަމުންގެ ރަބްބުގެ ޙަޟްރަތުން ބާވައިލެވުނު ވަޙީއެކެވެ. 56:80; 69:43
- = އުޑުތަކުގައި ހުރި އެއްޗާއި ބިމުގައި ހުރި އެއްޗެއް ﷲ ގެ ތަސްބީޙަ ކިޔައެވެ، އަދި އެކަލާނގެއަކީ ބާރުގަދަ، ޙިކުމަތްތެރި ފަރާތެވެ. 59:1; 61:1
- = އޭނާއަށް އަހަރެމެންގެ އާޔަތްތައް ކިޔައިދެވުނުހިނދު، އޭނާ ބުނެއެވެ: "ކުރީގެ މީހުންގެ ވާހަކަތަކެވެ." 68:15; 83:13
- = ފަހެ އޭނާ ހިތްހަމަޖެހޭ ދިރިއުޅުމެއްގައި ހުންނާނެއެވެ. 69:21; 101:7
- = މަތިވެރި ބަގީޗާއެއްގައެވެ. 69:22; 88:10
- = އަދި ފަގީރުންނަށް ކާންދިނުމަށް ހިތްވަރު ނުދެއެވެ. 69:34; 107:3
- = [ކަމަކީ] ހަމަކަށަވަރުން ޤުރުއާނަކީ ޝަރަފުވެރި ރަސޫލެއްގެ ބަސްފުޅެވެ. 69:40; 81:19
- = ހަމަކަށަވަރުން މިއީ ހަނދާންކޮށްދިނުމެކެވެ، ފަހެ ބޭނުންވާ މީހަކަށް އޭނާގެ ރަބްބުގެ ގާތަށް މަގެއް ހިފިދާނެއެވެ. 73:19; 76:29
- = ފަހެ ބޭނުންވާ މީހަކަށް އެކަން ހަނދާންކުރެވިދާނެއެވެ. 74:55; 80:12
